def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 584.2995691967869  # OPT_PARAM: {"initial": 584.2995691967869, "min": 400.0, "max": 900.0, "type": "float"}
    max_order = 86.86437357444422  # OPT_PARAM: {"initial": 86.86437357444422, "min": 80.0, "max": 300.0, "type": "float"}
    boost_param = 0.11465926583001033  # OPT_PARAM: {"initial": 0.11465926583001033, "min": 0.0, "max": 5.0, "type": "float"}
    adapt_param = 1.0808805002910402  # OPT_PARAM: {"initial": 1.0808805002910402, "min": 0.0, "max": 5.0, "type": "float"}
    ip = on_hand_inventory + sum(pipeline_orders)
    L = len(pipeline_orders)
    pipe_avg = sum(pipeline_orders) / L if L > 0 else 0.0
    effective_base = base_stock + adapt_param * pipe_avg
    uncapped_order = max(0.0, effective_base - ip)
    ratio = ip / max(effective_base, 1.0)
    shortfall_ratio = max(0.0, 1.0 - ratio)
    boost_factor = boost_param * (shortfall_ratio ** 3.0)
    effective_max_order = max_order * (1.0 + boost_factor)
    order_amount = min(uncapped_order, effective_max_order)
    return order_amount
